<script setup lang="ts">
import { computed, reactive, ref } from 'vue'
import { RouterLink, useRoute, useRouter } from 'vue-router'
import { api, ApiError, initializeCsrf } from '../../api/client'
import AppIcon from '../../components/AppIcon.vue'
import { useAuthStore } from '../../stores/auth'

const props = withDefaults(defineProps<{ registerMode?: boolean; adminMode?: boolean }>(), { registerMode: false, adminMode: false })
const route = useRoute(); const router = useRouter(); const auth = useAuthStore()
const form = reactive({ username:'', password:'', display_name:'', email:'' })
const busy = ref(false); const error = ref('')
const title = computed(() => props.registerMode ? '创建校园账户' : props.adminMode ? '进入运营工作台' : '欢迎回到拾光')
async function submit(){ busy.value=true; error.value=''; try { if(props.registerMode){ await initializeCsrf(); const response=await api<{data:any}>('/auth/register/',{method:'POST',body:JSON.stringify(form)}); auth.user=response.data } else { await auth.login(form.username,form.password); if(props.adminMode && !auth.isManagement){ await auth.logout(); throw new ApiError('该账户没有运营后台权限','role_forbidden',403) } } await router.push(String(route.query.redirect || (props.adminMode ? '/admin/overview' : '/home'))) } catch(reason){ error.value=reason instanceof ApiError?reason.message:'操作失败，请稍后重试' } finally{busy.value=false} }
</script>

<template><main class="auth-page"><RouterLink class="brand" to="/home"><span class="brand-mark"><AppIcon name="spark" /></span><span><strong>拾光</strong><small>CampusTrace</small></span></RouterLink><section class="auth-card"><div class="auth-copy"><p class="eyebrow">{{ adminMode ? 'AUDITED OPERATIONS ACCESS' : 'SECURE CAMPUS ACCESS' }}</p><h1>{{ title }}</h1><p>{{ registerMode ? '注册后即可发布线索、运行智能匹配与发起认领。' : adminMode ? '仅限站点协调员和系统管理员，所有管理写操作均进入审计记录。' : '登录后继续处理你的发布、匹配、认领和交接待办。' }}</p><ul><li><AppIcon name="shield"/>Session + CSRF 双重保护</li><li><AppIcon name="spark"/>可解释的六因子智能匹配</li><li><AppIcon name="map"/>站点范围与字段级隐私</li></ul></div><form @submit.prevent="submit"><label v-if="registerMode"><span>显示名称</span><input v-model="form.display_name" required autocomplete="name"/></label><label><span>用户名</span><input v-model="form.username" required autocomplete="username"/></label><label v-if="registerMode"><span>邮箱</span><input v-model="form.email" required type="email" autocomplete="email"/></label><label><span>密码</span><input v-model="form.password" required type="password" :autocomplete="registerMode ? 'new-password' : 'current-password'"/><small v-if="registerMode">至少 10 位，不能是常见密码或纯数字。</small></label><p v-if="error" class="error">{{ error }}</p><button class="button button-brand" :disabled="busy">{{ busy ? '正在安全处理…' : registerMode ? '注册并进入系统' : adminMode ? '进入运营工作台' : '登录' }}</button><p class="switch" v-if="!adminMode">{{ registerMode ? '已有账户？' : '第一次使用？' }} <RouterLink :to="registerMode ? '/login' : '/register'">{{ registerMode ? '返回登录' : '创建账户' }}</RouterLink></p><p class="switch" v-if="!registerMode"><RouterLink to="/recover">忘记密码或用户名？</RouterLink></p></form></section><p class="auth-footer">校园测试演示环境 · 不在公开页面展示精确地点和联系方式</p></main></template>

<style scoped>
.auth-page{display:grid;grid-template-rows:auto 1fr auto;min-height:100vh;padding:28px;background:radial-gradient(circle at 20% 20%,rgba(98,180,255,.18),transparent 30rem),radial-gradient(circle at 80% 80%,rgba(245,185,66,.12),transparent 28rem),var(--ct-bg)}.auth-page>.brand{justify-self:start}.auth-card{display:grid;grid-template-columns:1fr 1fr;overflow:hidden;width:min(940px,100%);margin:auto;border:1px solid var(--ct-border);border-radius:28px;background:var(--ct-surface);box-shadow:var(--ct-shadow)}.auth-copy{padding:55px;background:linear-gradient(150deg,rgba(24,63,98,.9),rgba(9,22,38,.95))}.auth-copy h1{margin:18px 0 12px;font-family:Georgia,"Songti SC",serif;font-size:42px}.auth-copy>p{color:var(--ct-text-muted);line-height:1.8}.auth-copy ul{display:grid;gap:18px;margin:40px 0 0;padding:0;list-style:none}.auth-copy li{display:flex;align-items:center;gap:10px;color:var(--ct-text-muted)}.auth-copy li svg{color:var(--ct-brand)}form{display:grid;align-content:center;gap:18px;padding:55px}label span{display:block;margin-bottom:8px;color:var(--ct-text-muted);font-size:12px}input{width:100%;padding:13px;color:var(--ct-text);border:1px solid var(--ct-border);border-radius:11px;background:var(--ct-bg-soft)}label small{display:block;margin-top:6px;color:var(--ct-text-muted)}form>.button{width:100%;margin-top:6px}.switch{text-align:center;color:var(--ct-text-muted)}.switch a{color:var(--ct-brand)}.error{padding:11px;color:var(--ct-danger);background:rgba(255,111,120,.08);border-radius:9px}.auth-footer{justify-self:center;color:var(--ct-text-muted);font-size:11px}@media(max-width:760px){.auth-card{grid-template-columns:1fr}.auth-copy{display:none}form{padding:32px}.auth-page{padding:18px}}
</style>
